DROP POLICY IF EXISTS "public insert audience_selections" ON public.audience_selections;
DROP POLICY IF EXISTS "anyone can insert cohort trials" ON public.cohort_trials;
DROP POLICY IF EXISTS "anyone can read cohort trials" ON public.cohort_trials;
DROP POLICY IF EXISTS "public insert eligibility_checks" ON public.eligibility_checks;
DROP POLICY IF EXISTS "public read eligibility_checks" ON public.eligibility_checks;
DROP POLICY IF EXISTS "anyone can create cohorts" ON public.saved_cohorts;
DROP POLICY IF EXISTS "anyone can read cohorts" ON public.saved_cohorts;
DROP POLICY IF EXISTS "public insert mapping_overrides" ON public.mapping_overrides;
DROP POLICY IF EXISTS "public read mapping_overrides" ON public.mapping_overrides;
DROP POLICY IF EXISTS "public insert ui_interactions" ON public.ui_interactions;
DROP POLICY IF EXISTS "public read site_barriers" ON public.site_barriers;
DROP POLICY IF EXISTS "public read acs_barriers_cache" ON public.acs_barriers_cache;
REVOKE ALL ON TABLE public.audience_selections, public.cohort_trials, public.eligibility_checks, public.saved_cohorts, public.mapping_overrides, public.ui_interactions, public.site_barriers, public.acs_barriers_cache, public.admin_access_sessions, public.admin_login_limits, public.issue_reports, public.report_feedback, public.result_feedback, public.result_interactions, public.search_events, public.search_refinements, public.session_outcomes, public.search_eval_cases, public.search_eval_runs FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.audience_selections, public.cohort_trials, public.eligibility_checks, public.saved_cohorts, public.mapping_overrides, public.ui_interactions, public.site_barriers, public.acs_barriers_cache, public.admin_access_sessions, public.admin_login_limits, public.issue_reports, public.report_feedback, public.result_feedback, public.result_interactions, public.search_events, public.search_refinements, public.session_outcomes, public.search_eval_cases, public.search_eval_runs TO service_role;
REVOKE ALL ON FUNCTION public.search_registry_impact() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_registry_impact() TO service_role;
COMMENT ON FUNCTION public.search_registry_impact() IS 'Legacy historical activity aggregate. Service role only; never expose public visitor queries.';
COMMENT ON TABLE public.saved_cohorts IS 'DEPRECATED: public cohort persistence retired; historical records retained with service role access only.';
COMMENT ON TABLE public.eligibility_checks IS 'DEPRECATED: public document reviews are not retained; historical records locked to service role.';